    {
        Capture.StopStream();
        Capture.CloseStream();
        bCaptureStreamOpen = false;
    }

    Super::EndPlay(EndPlayReason);
}

void AMyGameMode::OnAudioCaptured(
    const float* AudioData,
    int32 NumFrames,
    int32 NumChannels,
    int32 SampleRate,
    double StreamTime,
    bool bOverflow)
{
    // This callback runs on the audio-capture thread.
    // AudioData is only safe to use during the callback; copy it to a
